import type { TableName } from '../db';
import type { FlowSchemaType, FlowValueType, FlowIOType, OutputsWithDotwalk, OutputsWithDependentTable, ExtractDependentField } from './FlowTypes';
/**
 * Defines the configuration structure for an action.
 * This type is used by the `ActionDefinition` function to specify the properties of an action.
 * @template I - A record defining the input parameters for the action, where keys are input names
 *               and values are `FlowValueType`.
 * @template O - A record defining the output parameters for the action, where keys are output names
 *               and values are `FlowValueType`.
 */
export type ActionConfig<I extends Record<string, FlowValueType>, O extends Record<string, FlowValueType>> = Now.Internal.WithID<{
    /** The display name of the action. */
    name: string;
    /** Default annotation text for the action when used in a flow. */
    annotation?: string;
    /** A detailed description of what the action does. Visible to flow developers. */
    description?: string;
    /** Access level, e.g., 'public' or 'private' to a specific scope. */
    access?: 'public' | 'package_private';
    /** Category to group the action with, often a reference to `sys_hub_category`. */
    category?: string;
    /** Definitions for the input parameters of the action. */
    protection?: 'read' | '';
    inputs: I;
    /** Definitions for the output parameters of the action. */
    outputs: O;
}>;
/**
 * Represents the callable signature and structure of a defined action.
 * It's a function that takes an ID and inputs, and returns outputs.
 * It also holds the `inputs` and `outputs` type definitions as properties.
 * @template I - The inferred TypeScript type for the action's inputs (derived from `FlowSchemaType`).
 * @template O - The inferred TypeScript type for the action's outputs (derived from `FlowSchemaType`).
 * @template RawO - The raw outputs schema (FlowValueType) for checking dependent fields.
 */
type Action<I, O, RawO extends Record<string, FlowValueType> = Record<string, FlowValueType>> = {
    /**
     * Invokes the action.
     * @param id - An identifier for this specific instance of the action.
     * @param inputs - The input data for the action, conforming to the inferred input schema.
     * @returns The output data from the action, conforming to the inferred output schema.
     */
    <TInputs extends I>(id: string, inputs: TInputs & I): O;
    /** The schema definition for the action's inputs. */
    inputs: I;
    /** The schema definition for the action's outputs. */
    outputs: O;
    /** The raw outputs schema for dependent field resolution. */
    rawOutputs: RawO;
};
/**
 * Check if a column is a DocumentIdColumn by looking for the 'dependent' property.
 * DocumentIdColumn is the only column type that has a required 'dependent' property.
 */
type IsDocumentIdColumn<C> = C extends {
    dependent: string;
} ? true : false;
/**
 * Find the first DocumentIdColumn output field that has a 'dependent' property and extract its dependent field name.
 * Returns the dependent field name (e.g., 'table_name', 'source_table') or never if none found.
 * Only considers DocumentIdColumn outputs, not other columns that might have a dependent property.
 */
type FindDependentFieldName<O extends Record<string, FlowValueType>> = {
    [K in keyof O]: IsDocumentIdColumn<O[K]> extends true ? ExtractDependentField<O[K]> : never;
}[keyof O];
/**
 * Check if an output schema has any field with a 'dependent' property.
 */
type HasDependentOutput<O extends Record<string, FlowValueType>> = FindDependentFieldName<O> extends never ? false : true;
/**
 * Extract the table name from inputs using the dependent field name.
 * Dynamically looks up the field specified by the 'dependent' property in the output.
 *
 * @template TInputs - The inputs object
 * @template DependentField - The field name to look up (from output's dependent property)
 */
type ExtractInputTableByField<TInputs, DependentField extends string> = DependentField extends keyof TInputs ? TInputs[DependentField] extends TableName ? TInputs[DependentField] : never : never;
/**
 * Extract the table name from inputs based on the dependent field name found in outputs.
 */
type ExtractInputTable<TInputs, RawO extends Record<string, FlowValueType>> = ExtractInputTableByField<TInputs, FindDependentFieldName<RawO> & string>;
/**
 * Resolve action outputs with dependent table awareness.
 * If the action has outputs with 'dependent' fields pointing to table inputs,
 * and we know the table from inputs, provide table-aware typing.
 *
 * When O is any (e.g., for getCatalogVariables), returns any to allow arbitrary property access.
 *
 * @template O - The transformed outputs type (OutputsWithDotwalk applied)
 * @template RawO - The raw outputs schema (for checking dependent fields)
 * @template TInputs - The actual inputs provided to the action
 *
 * @example
 * ```typescript
 * // IntelliSense shows fields from 'incident' table on result.record
 * const result = wfa.action(
 *     action.core.createRecord,
 *     { $id: Now.ID['create_incident'] },
 *     { table_name: 'incident', values: '' }
 * )
 * result.record.number  // IntelliSense for incident fields
 * result.record.short_description
 * ```
 */
type ResolveActionOutputs<O, RawO extends Record<string, FlowValueType>, TInputs> = [O] extends [any] ? any : HasDependentOutput<RawO> extends true ? ExtractInputTable<TInputs, RawO> extends never ? O : OutputsWithDependentTable<RawO, ExtractInputTable<TInputs, RawO>> : O;
/**
 * Creates a new Action Type (`sys_hub_action_type_definition`).
 * This function defines the metadata and schema for a reusable action within the Flow system.
 *
 * @template I - A record defining the input parameters using `FlowValueType`.
 * @template O - A record defining the output parameters using `FlowValueType`.
 * @param _config - An object adhering to `ActionConfig` but with `FlowValueType` for inputs/outputs:
 *   * **$id** - Unique ID for the record, typically using `Now.ID["value"]`.
 *   * **name** - Display name for the action.
 *   * **natlang**? - Natural language phrase for the action.
 *   * **description**? - Detailed explanation of the action's purpose.
 *   * **annotation**? - Default annotation text when used in a flow.
 *   * **access**? - Scope accessibility (e.g., 'All application scopes').
 *   * **category**? - Reference to `sys_hub_category` for grouping.
 *   * **inputs** - Input definitions using `FlowValueType`.
 *   * **outputs** - Output definitions using `FlowValueType`.
 * @returns A callable `Action` object, typed with inferred input and output schemas
 *          (transformed by `FlowSchemaType`). Currently, the implementation returns `undefined`
 *          and likely serves as a type definition or registration mechanism.
 */
export declare function ActionDefinition<I extends Record<string, FlowValueType>, O extends Record<string, FlowValueType>>(_config: ActionConfig<I, O>, _body?: (inputs: FlowSchemaType<I>, outputs: FlowSchemaType<O>) => void): Action<FlowIOType<I>, OutputsWithDotwalk<O>, O>;
/**
 * Configuration object for Action instances
 */
type ActionInstanceConfig = Now.Internal.WithID<{
    /** Optional annotation text for this specific action instance */
    annotation?: string;
    uuid?: string;
}>;
/**
 * Default outputs available on all action instances.
 * These are system-provided outputs that exist regardless of the action definition.
 */
type DefaultActionOutputs = {
    /** Status information for the action execution */
    __action_status__: {
        /** Status code of the action execution */
        code: number;
        /** Status message describing the result */
        message: string;
    };
    __dont_treat_as_error__: boolean;
};
/**
 * Helper type for action outputs when the action definition is not available (sys_id fallback).
 * Allows arbitrary property access for datapill references without TypeScript errors.
 * This is effectively `any` but typed in a way that allows dot notation property access.
 */
type UnknownActionOutputs = any;
/**
 * A generic function that represents an instance or invocation of an action.
 * Uses the configuration object format with $id and optional annotation.
 *
 * This function has two overloads:
 * 1. When an Action definition is provided: Returns typed outputs with known properties
 * 2. When a string (sys_id) is provided: Returns outputs with arbitrary property access support
 */
/**
 * Helper type to ensure exact object shape - disallows excess properties
 * @template T - The required type
 * @template U - The actual type being checked
 */
type Exact<T, U extends T> = U & Record<Exclude<keyof U, keyof T>, never>;
/**
 * Action instance with known Action definition - provides type-safe output property access
 * with table-aware typing for outputs with dependent fields.
 * Enforces exact input matching - excess properties not defined in the action will cause type errors.
 * @template I - The type of the input parameters for the action.
 * @template O - The type of the output parameters for the action.
 * @template RawO - The raw outputs schema (FlowValueType) for checking dependent fields.
 * @template TInputs - The actual input type being passed, which must exactly match I (no excess properties).
 * @param _action - The `Action` object (created by `ActionDefinition`).
 * @param _config - Configuration object with $id and optional annotation.
 * @param _inputs - The input data provided to the action. Must match the action definition exactly.
 * @returns The expected output of the action, with table-aware typing when applicable.
 *
 * @example
 * ```typescript
 * // IntelliSense shows fields from 'incident' table on result.record
 * const result = wfa.action(
 *     action.core.createRecord,
 *     { $id: Now.ID['create_incident'] },
 *     { table_name: 'incident', values: '' }
 * )
 * result.record.number  // IntelliSense for incident fields
 * result.record.short_description
 * ```
 */
export declare function Action<I, O, RawO extends Record<string, FlowValueType>, const TInputs extends I>(_action: Action<I, O, RawO>, _config: ActionInstanceConfig, _inputs: Exact<I, TInputs>): ResolveActionOutputs<O, RawO, TInputs> & {
    type: 'action';
} & DefaultActionOutputs;
/**
 * Action instance with sys_id fallback - allows arbitrary property access for datapill references
 * @param _action - A string sys_id when the action definition cannot be resolved.
 * @param _config - Configuration object with $id and optional annotation.
 * @param _inputs - The input data provided to the action (untyped).
 * @returns An object with arbitrary property access to support datapill references like `.name`, `.age`, etc.
 */
export declare function Action(_action: string, _config: ActionInstanceConfig, _inputs: Record<string, any>): {
    type: 'action';
} & DefaultActionOutputs & UnknownActionOutputs;
export {};
